package robofight.fireline

import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertNotNull
import kotlin.test.assertTrue

/**
 * W2 arithmetic audit, empirical half (docs/FIRELINE-WEB.md §10 risk "Long/Int
 * drift on wasmJs or js"). The engine's own numeric primitives plus the raw
 * 32/64-bit behaviors every container must reproduce are evaluated HERE, on
 * whichever target runs the test, and compared against the values recorded from
 * the JVM run ([PARITY_ARITH_VECTORS], generated by `docs/web/fixtures/ParityMatrix.kt`).
 *
 * If wasmJs arithmetic differed anywhere the engine depends on - i64 wrap
 * multiplication, i32 shift/remainder sign rules, `Int` truncation - the value
 * on the wasm target would not match and this suite fails on that target only,
 * which is exactly the signal a fingerprint drift would produce later.
 */
class W2ArithmeticParityTest {

    private fun hex(v: Long): String = v.toULong().toString(16).padStart(16, '0')

    private fun fnvLong(text: String): Long {
        var h = FNV_OFFSET_BASIS
        for (c in text) h = (h xor c.code.toLong()) * FNV_PRIME
        return h
    }

    private fun bytes(stream: LcgStream): String =
        (0 until 12).joinToString(",") { stream.nextByte().toString() }

    /** Every probe recomputed on the running target. Names must match the recorded set. */
    private fun liveVector(): Map<String, String> {
        val m = LinkedHashMap<String, String>()
        m["rng_sensor_1001"] = bytes(LcgStream.forSensor(1001))
        m["rng_spread_2002"] = bytes(LcgStream.forSpread(2002))
        m["rng_layout_3003"] = bytes(LcgStream.forLayout(3003))
        m["rng_next_of_wrap"] = LcgStream.nextOf(0x7FFFFFFF).toString()
        m["rng_byte_of_min"] = LcgStream.byteOf(-1).toString()

        m["fnv_offset_basis"] = hex(FNV_OFFSET_BASIS)
        m["fnv_prime"] = hex(FNV_PRIME)
        m["fnv_empty"] = hex(fnvLong(""))
        m["fnv_ascii"] = hex(fnvLong("OPCODE FIRELINE // W2 parity probe"))
        m["fnv_high_utf16"] = hex(fnvLong("«Ω€"))
        m["fnv_long_text"] = hex(fnvLong("FIRELINE W2 parity probe ".repeat(400)))

        m["int_add_overflow"] = (Int.MAX_VALUE + 1).toString()
        m["int_sub_underflow"] = (Int.MIN_VALUE - 1).toString()
        m["int_mul_overflow"] = (65536 * 65536).toString()
        m["mod_neg_dividend"] = (-7 % 3).toString()
        m["mod_neg_divisor"] = (7 % -3).toString()
        m["mod_both_neg"] = (-7 % -3).toString()
        m["div_trunc_neg"] = (-7 / 2).toString()
        m["shl_sign_bit"] = (1 shl 31).toString()
        m["neg_shl31"] = (-1 shl 31).toString()
        m["neg_arith_shr1"] = (-1 shr 1).toString()
        m["neg_logic_shr1"] = (-1 ushr 1).toString()
        m["long_mul_wrap"] = (0x3FFFFFFFFFFFFFFFL * 4L).toString()
        m["long_to_int_truncate"] = 0xFFFFFFFF1234L.toInt().toString()
        m["int_to_long_sign_extend"] = (-1).toLong().toString()
        m["long_signed_max"] = Long.MAX_VALUE.toString()
        m["long_signed_min"] = Long.MIN_VALUE.toString()
        m["long_unsigned_shr1"] = hex((-1L) ushr 1)
        m["mask_and_signed"] = (0x7FFFFFFF and (-1)).toString()
        return m
    }

    @Test
    fun everyRecordedArithmeticProbeReproducesOnThisTarget() {
        val live = liveVector()
        assertEquals(PARITY_ARITH_VECTORS.size, live.size, "probe set drifted from the recorded set")
        for ((name, expected) in PARITY_ARITH_VECTORS) {
            val actual = assertNotNull(live[name], "recorded probe $name is no longer evaluated")
            assertEquals(expected, actual, "probe $name (container arithmetic drift?)")
        }
    }

    @Test
    fun engineNumericPrimitivesAreInRangeAndWrapWhereDocumented() {
        // The audit's structural claims, checked rather than assumed.
        assertEquals(-2147483648, liveInt("int_add_overflow"), "Int wraps two's complement, no promotion")
        assertEquals(-60876, liveInt("long_to_int_truncate"), "Long -> Int keeps the low 32 bits, signed")
        assertEquals(0x7FFFFFFF, LcgStream.STATE_MASK, "LCG state stays a positive 31-bit Int")
        assertTrue(LcgStream.nextOf(0x7FFFFFFF) in 0..LcgStream.STATE_MASK, "LCG next state stays in mask")
        assertTrue(LcgStream.byteOf(-1) in 0..255, "LCG byte extraction is always a positive byte")
        assertEquals(FIRELINE_ENGINE_VERSION, 1, "the recorded fingerprints are stamped v1")
    }

    private fun liveInt(name: String): Int = assertNotNull(liveVector()[name]).toInt()
}
